from candidate import fibfib
import pytest
from unittest.mock import patch

@pytest.mark.parametrize("n, expected", [
    (1, 0), (5, 4), (8, 24), (10, 89), (15, 274), (20, 1770), (25, 10609)
])
def test_fibfib_normalcases(n, expected):
    assert fibfib(n) == expected

@pytest.mark.parametrize("n", [
    -1, -2, -3, -100, 1000, float('inf')
])
def test_fibfib_edgecases(n):
    with pytest.raises(ValueError):
        fibfib(n)

@pytest.mark.parametrize("n", [None])
def test_fibfib_none_input(n):
    with pytest.raises(TypeError):
        fibfib(n)

@pytest.mark.parametrize("n", [0, 1, 2])
def test_fibfib_boundary_conditions(n):
    assert fibfib(n) == [0, 0, 1][n]

@pytest.mark.parametrize("n", [
    (3,), (4,), (5,)
])
def test_fibfib_nonsequential_inputs(n):
    assert fibfib(n) == [1, 1, 2, 4, 9][n]

@pytest.mark.parametrize("n", [
    (10,), (15,), (20,), (25,)
])
def test_fibfib_large_values(n):
    assert fibfib(n) < 10000

@pytest.mark.parametrize("n", [
    (3,), (4,), (5,)
])
def test_fibfib_caching(n):
    with patch('builtins.input', side_effect=['4']):
        assert fibfib(4) == 9

def test_fibfib_multiplication():
    assert fibfib(4) * 2 == 18
    assert fibfib(4) * 0 == 0
    assert fibfib(4) * -1 == -18
    assert fibfib(4) == fibfib(4) * 1

def test_fibfib_mixed_inputs():
    assert fibfib(1) == 0
    assert fibfib(1.5) == 0
    assert fibfib(1 + 1.5) == 0
    assert fibfib("1") == 0
    assert fibfib([1]) == 0
    assert fibfib({'n': 1}) == 0
